package com.bank.cloud.model;

// One security control in the deployment.
public class CloudControl {
    private final String name;
    private final ResponsibleParty party;
    private final ComplianceState state;
    private final String detail;       // human-readable reason

    public CloudControl(String name, ResponsibleParty party, ComplianceState state, String detail) {
        this.name = name;
        this.party = party;
        this.state = state;
        this.detail = detail;
    }

    public String getName() { return name; }
    public ResponsibleParty getParty() { return party; }
    public ComplianceState getState() { return state; }
    public String getDetail() { return detail; }

    // A breach risk is a CUSTOMER control that is MISCONFIGURED.
    public boolean isBreachRisk() {
        return party == ResponsibleParty.CUSTOMER && state == ComplianceState.MISCONFIGURED;
    }
}
