package com.bank.cloud.classify;

import com.bank.cloud.model.CloudControl;
import com.bank.cloud.model.ResponsibleParty;
import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Collectors;

// Splits the controls into provider-owned and customer-owned.
public class ResponsibilityClassifier {
    private static final Logger log = Logger.getLogger(ResponsibilityClassifier.class.getName());

    public List<CloudControl> providerControls(List<CloudControl> all) {
        List<CloudControl> provider = all.stream()
                .filter(c -> c.getParty() == ResponsibleParty.PROVIDER)
                .collect(Collectors.toList());
        log.info(() -> "Provider secures " + provider.size()
                + " control(s) — bank need not audit these");
        return provider;
    }

    public List<CloudControl> customerControls(List<CloudControl> all) {
        List<CloudControl> customer = all.stream()
                .filter(c -> c.getParty() == ResponsibleParty.CUSTOMER)
                .collect(Collectors.toList());
        log.info(() -> "Bank is accountable for " + customer.size() + " control(s)");
        return customer;
    }
}
