package com.bank.cloud.audit;

import com.bank.cloud.model.CloudControl;
import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Collectors;

// Reports the customer-side misconfigurations — the real breach surface.
public class BreachRiskAuditor {
    private static final Logger log = Logger.getLogger(BreachRiskAuditor.class.getName());

    public List<CloudControl> findBreachRisks(List<CloudControl> customerControls) {
        List<CloudControl> risks = customerControls.stream()
                .filter(CloudControl::isBreachRisk)
                .collect(Collectors.toList());

        if (risks.isEmpty()) {
            log.info("No customer-side misconfigurations — breach surface is clean");
        } else {
            for (CloudControl r : risks) {
                log.severe(() -> "BREACH RISK (customer-owned): " + r.getName()
                        + " — " + r.getDetail());
            }
        }
        return risks;
    }
}
