package com.bank.cloud;

import com.bank.cloud.audit.BreachRiskAuditor;
import com.bank.cloud.classify.ResponsibilityClassifier;
import com.bank.cloud.model.CloudControl;
import com.bank.cloud.model.ComplianceState;
import com.bank.cloud.model.ResponsibleParty;
import java.util.List;
import java.util.logging.Logger;

// Runnable demo: four controls matching the four banking problems.
public class CloudAuditApplication {
    private static final Logger log = Logger.getLogger(CloudAuditApplication.class.getName());

    public static void main(String[] args) {
        // Problem 1: statements bucket left public — customer misconfiguration.
        CloudControl bucket = new CloudControl("statements-bucket-access",
                ResponsibleParty.CUSTOMER, ComplianceState.MISCONFIGURED,
                "bucket set to PUBLIC read — statements exposed to the internet");

        // Problem 2: wildcard role policy — over-permissioned identity.
        CloudControl role = new CloudControl("service-iam-role",
                ResponsibleParty.CUSTOMER, ComplianceState.MISCONFIGURED,
                "role grants all-actions-on-all-resources — blast radius = whole account");

        // Problem 3: data center + hypervisor — provider responsibility.
        CloudControl datacenter = new CloudControl("physical-datacenter+hypervisor",
                ResponsibleParty.PROVIDER, ComplianceState.COMPLIANT,
                "hardware and hypervisor patched by provider");

        // Problem 4: encryption + logging done right — compliant customer control.
        CloudControl encryption = new CloudControl("encryption-at-rest+audit-logging",
                ResponsibleParty.CUSTOMER, ComplianceState.COMPLIANT,
                "bucket encrypted and audit logging enabled");

        List<CloudControl> all = List.of(bucket, role, datacenter, encryption);

        ResponsibilityClassifier classifier = new ResponsibilityClassifier();
        BreachRiskAuditor auditor = new BreachRiskAuditor();

        log.info("=== National Bank of India — Shared Responsibility audit ===");
        classifier.providerControls(all);
        List<CloudControl> customerOwned = classifier.customerControls(all);
        List<CloudControl> risks = auditor.findBreachRisks(customerOwned);
        log.info(() -> "Bank must remediate " + risks.size() + " control(s) to close breach surface");
    }
}
